import subprocess
import shutil
import os
def task_func(script_path: str, temp_dir: str) -> str:
    if not isinstance(script_path, str) or not isinstance(temp_dir, str):
        return "Script execution failed!"
    if not os.path.isfile(script_path) or not os.path.isdir(temp_dir):
        return "Script execution failed!"
    try:
        dest_path = os.path.join(temp_dir, os.path.basename(script_path))
        shutil.copy(script_path, dest_path)
        original_cwd = os.getcwd()
        os.chdir(temp_dir)
        result = subprocess.run(['python', dest_path], capture_output=True, shell=True)
        os.chdir(original_cwd)
        if result.returncode == 0:
            return "Script executed successfully!"
        else:
            return "Script execution failed!"
    except Exception:
        return "Script execution failed!"

import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    system = platform.system()
    if system == "Windows":
        cmd = ["wmic", "cpu", "get", "loadpercentage"]
    else:
        cmd = ["top", "-bn1"]
    records = []
    start_time = time.time()
    while time.time() - start_time < duration:
        timestamp = time.time()
        try:
            output = subprocess.check_output(cmd, shell=True).decode()
            if system == "Windows":
                lines = output.strip().split('\n')
                cpu_usage = float(lines[1].strip())
            else:
                for line in output.split('\n'):
                    if "Cpu(s)" in line:
                        cpu_usage = 100.0 - float(line.split()[7].replace(',', '.'))
                        break
        except:
            cpu_usage = 0.0
        records.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
    except IOError:
        return None
    return LOGFILE_PATH

